mapper.sql:
WHERE
		M.STATUS_CODE IN (9, 2)



	AND M.LOCGOV_CODE = (SELECT LOCGOV_CODE FROM OP_MANAGER WHERE USER_ID = #{loginUserId})




	AND M.BANK_CODE = (SELECT BANK_CODE FROM OP_MANAGER WHERE USER_ID = #{loginUserId})






			AND CONCAT(L.UPPER_LOCGOV_NM, ' ', L.LOCGOV_NM) LIKE CONCAT('%', #{srchValue},'%')


			AND M.LOGIN_ID = (SELECT crypto_enc('normal', #{srchValue}, ''))


			AND M.USER_NAME = (SELECT crypto_enc('normal', #{srchValue}, ''))


			AND M.PHONE_NUMBER = (SELECT crypto_enc('normal', #{srchValue}, ''))


			AND M.PSITN_NM LIKE CONCAT('%', #{srchValue},'%')


			AND M.EMP_ID = (SELECT crypto_enc('normal', #{srchValue}, ''))






	AND DATE_FORMAT(M.CREATED_DATE,'%Y%m%d')  >=  #{srchStartCreated}




	AND DATE_FORMAT(M.CREATED_DATE,'%Y%m%d')  <=  #{srchEndCreated}




	AND M.STATUS_CODE = #{srchStatusCode}




	AND R.AUTHORITY IN (

			#{item}

	)

mapper.select:
/** slave-personincharge-mapper.getChargerCountByParam (담당자 관리 목록 갯수 조회 ) */ SELECT COUNT(*) FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
)

/** slave-personincharge-mapper.getChargerListByParam (담당자 관리 목록 조회) */ SELECT A.LOCGOV_CODE , B.LOCGOV_NM , B.UPPER_LOCGOV_CODE , B.UPPER_LOCGOV_NM , A.AUTHORITY , crypto_dec('normal', A.LOGIN_ID, '', 0) AS LOGIN_ID , crypto_dec('normal', A.USER_NAME, '', 0) AS USER_NAME , crypto_dec('normal', A.PHONE_NUMBER, '', 0) AS PHONE_NUMBER , DATE_FORMAT(A.CREATED_DATE,'%Y-%m-%d') AS CREATED_DATE , A.STATUS_CODE , DATE_FORMAT(A.DENY_DATE,'%Y-%m-%d') AS DENY_DATE , A.USER_ID , A.PSITN_DEPT_NM , A.BANK_CODE , A.PSITN_NM , crypto_dec('normal', A.EMP_ID, '', 0) AS EMP_ID , A.BANK_NM FROM (
SELECT M.LOCGOV_CODE , R.AUTHORITY , M.LOGIN_ID , M.USER_NAME , M.PHONE_NUMBER , M.CREATED_DATE , M.STATUS_CODE , M.DENY_DATE , M.USER_ID , M.PSITN_DEPT_NM , M.BANK_CODE , M.PSITN_NM , M.EMP_ID , ( SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'OFF_BANK_LIST' AND C.USE_YN = 'Y' AND C.LANGUAGE = 'ko' AND C.ID = M.BANK_CODE) AS BANK_NM FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
)
ORDER BY BANK_NM, M.PSITN_NM
ORDER BY M.CREATED_DATE DESC
) A LEFT OUTER JOIN G_LOCGOV B ON A.LOCGOV_CODE = B.LOCGOV_CODE

/** slave-personincharge-mapper.getChargerDetails (담당자 상세 조회) */ SELECT L.LOCGOV_CODE , L.LOCGOV_NM , L.UPPER_LOCGOV_CODE , L.UPPER_LOCGOV_NM , R.AUTHORITY , crypto_dec('normal', M.LOGIN_ID, '', 0) AS LOGIN_ID , crypto_dec('normal', M.USER_NAME, '', 0) AS USER_NAME , crypto_dec('normal', M.PHONE_NUMBER, '', 0) AS PHONE_NUMBER , DATE_FORMAT(M.CREATED_DATE,'%Y-%m-%d') AS CREATED_DATE , M.STATUS_CODE , DATE_FORMAT(M.DENY_DATE,'%Y-%m-%d') AS DENY_DATE , M.USER_ID , M.BANK_CODE , crypto_dec('normal', M.EMP_ID, '', 0) AS EMP_ID , M.PSITN_NM , M.PSITN_DEPT_NM , crypto_dec('normal', M.OFCPS_NM, '', 0) AS OFCPS_NM , crypto_dec('normal', M.EMAIL, '', 0 ) AS EMAIL , ( SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'OFF_BANK_LIST' AND C.USE_YN = 'Y' AND C.LANGUAGE = 'ko' AND C.ID = M.BANK_CODE) AS BANK_NM FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
) LEFT OUTER JOIN G_LOCGOV L ON L.LOCGOV_CODE = M.LOCGOV_CODE WHERE M.STATUS_CODE IN (9, 2) AND M.USER_ID = #{userId}

/** slave-personincharge-mapper.getManagerInfoUpdateDate (관리자 정보갱신일자 조회) */
SELECT IFNULL(M.INFO_UPDT_DE, '') AS INFO_UPDT_DE
FROM OP_MANAGER M
WHERE M.USER_ID = #{userId}
AND M.STATUS_CODE = 9

/** slave-personincharge-mapper.getUserAdminRole (사용자 관리자 권한 조회) */
SELECT R.AUTHORITY
FROM OP_USER_ROLE R
WHERE R.USER_ID = #{userId}
AND R.AUTHORITY LIKE 'ROLE_ADMIN_%'
LIMIT 1

/** slave-personincharge-mapper.getLoginIdByUserId (로그인 아이디 조회) */
SELECT crypto_dec('normal', LOGIN_ID, '', 0) AS LOGIN_ID
FROM OP_MANAGER
WHERE USER_ID = #{userId}

/** slave-personincharge-mapper.getLocgovChargerCountByParam (담당자 관리 목록 갯수 조회 ) */ SELECT COUNT(*) FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
) INNER JOIN G_LOCGOV L ON L.LOCGOV_CODE = M.LOCGOV_CODE

/** slave-personincharge-mapper.getLocgovChargerListByParam (담당자 관리 목록 조회) */ SELECT A.LOCGOV_CODE , A.LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.UPPER_LOCGOV_NM , A.AUTHORITY , crypto_dec('normal', A.LOGIN_ID, '', 0) AS LOGIN_ID , crypto_dec('normal', A.USER_NAME, '', 0) AS USER_NAME , crypto_dec('normal', A.PHONE_NUMBER, '', 0) AS PHONE_NUMBER , DATE_FORMAT(A.CREATED_DATE,'%Y-%m-%d') AS CREATED_DATE , A.STATUS_CODE , DATE_FORMAT(A.DENY_DATE,'%Y-%m-%d') AS DENY_DATE , A.USER_ID , A.PSITN_DEPT_NM , A.BANK_CODE , A.PSITN_NM , crypto_dec('normal', A.EMP_ID, '', 0) AS EMP_ID , A.BANK_NM FROM (
SELECT M.LOCGOV_CODE , L.LOCGOV_NM , L.UPPER_LOCGOV_CODE , L.UPPER_LOCGOV_NM , R.AUTHORITY , M.LOGIN_ID , M.USER_NAME , M.PHONE_NUMBER , M.CREATED_DATE , M.STATUS_CODE , M.DENY_DATE , M.USER_ID , M.PSITN_DEPT_NM , M.BANK_CODE , M.PSITN_NM , M.EMP_ID , ( SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'OFF_BANK_LIST' AND C.USE_YN = 'Y' AND C.LANGUAGE = 'ko' AND C.ID = M.BANK_CODE) AS BANK_NM FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
) INNER JOIN G_LOCGOV L ON L.LOCGOV_CODE = M.LOCGOV_CODE
ORDER BY BANK_NM, M.PSITN_NM
ORDER BY M.CREATED_DATE DESC
) A
